# Série d'exercices de fin de chapitre — Chimie 5C/5D.
# k = "book" : exercice du manuel (src = page et numéro) ; "extra" : exercice du même type ; "int" : situation d'intégration.
SERIES = {}

SERIES["Chimie – Chapitre I : La réaction chimique et l’avancement"] = [
 {"k": "book", "src": "p. 25, ex. 4", "q": "1) Un comprimé contient m = 500 mg d’acide ascorbique C₆H₈O₆. Quelle quantité de matière contient-il ?\n2) Une gélule contient n = 8,04 mmol de chlorure de potassium KCl. Quelle masse de KCl absorbe-t-on ?\nDonnées : M(C₆H₈O₆) = 176,0 g/mol ; M(KCl) = 74,6 g/mol.",
  "a": "1) n = m/M = 0,500/176,0 ≈ 2,84 × 10⁻³ mol.\n2) m = n × M = 8,04 × 10⁻³ × 74,6 ≈ 0,600 g."},
 {"k": "book", "src": "p. 25, ex. 5", "q": "Deux récipients reliés par un robinet contiennent un gaz parfait à 27 °C : P₁ = 2,0 × 10⁵ Pa, V₁ = 2,0 L ; P₂ = 1,0 × 10⁵ Pa, V₂ = 5,0 L (R = 8,31 SI).\n1) Calculer n₁ et n₂. 2) On ouvre le robinet : volume total Vt ? 3) Pression finale Pt ?",
  "a": "T = 300 K. 1) n₁ = P₁V₁/(RT) = (2,0 × 10⁵ × 2,0 × 10⁻³)/(8,31 × 300) ≈ 0,160 mol ; n₂ = (1,0 × 10⁵ × 5,0 × 10⁻³)/2493 ≈ 0,201 mol.\n2) Vt = 7,0 L.\n3) Pt = (n₁ + n₂)RT/Vt = (400 + 500)/(7,0 × 10⁻³) ≈ 1,29 × 10⁵ Pa."},
 {"k": "book", "src": "p. 25, ex. 6", "q": "On verse V = 20,0 mL d’une solution de nitrate d’argent ([Ag⁺] = 0,15 mol/L) sur 0,127 g de poudre de cuivre ; la solution devient bleue et de l’argent se dépose.\na) Équation. b) État initial. c) Réactif limitant et avancement maximal. d) État final. e) Concentrations des ions et masses des solides à l’état final.\n(M(Cu) = 63,5 g/mol ; M(Ag) = 108 g/mol)",
  "a": "a) Cu + 2Ag⁺ → Cu²⁺ + 2Ag.\nb) n(Ag⁺) = 0,020 × 0,15 = 3,0 × 10⁻³ mol ; n(Cu) = 0,127/63,5 = 2,0 × 10⁻³ mol.\nc) Ag⁺ : 3,0 × 10⁻³ − 2x = 0 ⇒ x = 1,5 × 10⁻³ ; Cu : x = 2,0 × 10⁻³. Ag⁺ est limitant, xmax = 1,5 × 10⁻³ mol.\nd) Cu : 0,5 × 10⁻³ mol ; Ag⁺ : 0 ; Cu²⁺ : 1,5 × 10⁻³ mol ; Ag : 3,0 × 10⁻³ mol.\ne) [Cu²⁺] = 1,5 × 10⁻³/0,020 = 0,075 mol/L ; [NO₃⁻] = 0,15 mol/L. m(Cu) ≈ 0,032 g ; m(Ag) ≈ 0,324 g."},
 {"k": "book", "src": "p. 26, ex. 7", "q": "Un réservoir contient 42 L d’essence assimilée à l’heptane C₇H₁₆ (densité 0,755). La combustion est complète (CO₂ et H₂O). Vm = 25 L/mol.\na) Équation. b) Volume de dioxygène pour la moitié du réservoir. c) Pour la totalité. d) Volume de CO₂ formé (totalité).",
  "a": "a) C₇H₁₆ + 11 O₂ → 7 CO₂ + 8 H₂O.\nb) m = 42 × 0,755 = 31,71 kg ; n = 31 710/100 = 317,1 mol. Moitié : 158,6 mol ⇒ n(O₂) = 11 × 158,6 ≈ 1744 mol ⇒ V ≈ 43,6 m³.\nc) ≈ 87,2 m³.\nd) n(CO₂) = 7 × 317,1 ≈ 2220 mol ⇒ V ≈ 55,5 m³."},
 {"k": "book", "src": "p. 27, ex. 9", "q": "Combustion de la diméthylhydrazine : C₂H₈N₂ + N₂O₄ → N₂ + H₂O + CO₂.\n1) Équilibrer. 2) Quantités initiales pour 480 g de C₂H₈N₂ et 1288 g de N₂O₄. 3) Tableau d’avancement. 4) Composition finale et masses des produits.",
  "a": "1) C₂H₈N₂ + 2N₂O₄ → 3N₂ + 4H₂O + 2CO₂.\n2) M(C₂H₈N₂) = 60 g/mol ⇒ 8,0 mol ; M(N₂O₄) = 92 g/mol ⇒ 14 mol.\n3) xmax : 8,0 pour C₂H₈N₂, 14/2 = 7,0 pour N₂O₄ : N₂O₄ est limitant, xmax = 7,0 mol.\n4) C₂H₈N₂ : 1,0 mol ; N₂ : 21 mol (588 g) ; H₂O : 28 mol (504 g) ; CO₂ : 14 mol (616 g)."},
 {"k": "book", "src": "p. 27, ex. 10", "q": "3HO⁻ + Fe³⁺ → Fe(OH)₃. On mélange 20 mL de sulfate de fer (0,12 mol/L en Fe³⁺) et 2 mL de soude (0,5 mol/L).\na) Quantités initiales. b) Tableau d’avancement. c) État final. d) Quantités des réactifs quand il s’est formé 2 × 10⁻⁴ mol de Fe(OH)₃.",
  "a": "a) n(Fe³⁺) = 2,4 × 10⁻³ mol ; n(HO⁻) = 1,0 × 10⁻³ mol.\nb) HO⁻ : 1,0 × 10⁻³ − 3x ; Fe³⁺ : 2,4 × 10⁻³ − x ; Fe(OH)₃ : x.\nc) HO⁻ limitant : xmax ≈ 3,3 × 10⁻⁴ mol. Fe³⁺ restant ≈ 2,07 × 10⁻³ mol ; Fe(OH)₃ ≈ 3,3 × 10⁻⁴ mol.\nd) x = 2 × 10⁻⁴ : HO⁻ = 4,0 × 10⁻⁴ mol ; Fe³⁺ = 2,2 × 10⁻³ mol."},
 {"k": "book", "src": "p. 28, ex. 12", "q": "On fait réagir 0,60 g d’aluminium avec 6,0 mL d’acide chlorhydrique à 1,0 mol/L en H⁺ ; un gaz se dégage. Vm = 25 L/mol.\n1) Nature du gaz ? 2) Équation. 3) Quantités initiales. 4) Réactif limitant et volume de gaz dégagé.",
  "a": "1) Du dihydrogène (petite détonation).\n2) 2Al + 6H⁺ → 2Al³⁺ + 3H₂.\n3) n(Al) = 0,60/27 ≈ 2,2 × 10⁻² mol ; n(H⁺) = 6,0 × 10⁻³ mol.\n4) Al : x ≤ 1,1 × 10⁻² ; H⁺ : x ≤ 1,0 × 10⁻³. H⁺ est limitant, xmax = 1,0 × 10⁻³ mol ; n(H₂) = 3,0 × 10⁻³ mol, V = 75 mL."},
 {"k": "book", "src": "p. 28, ex. 13", "q": "Synthèse de l’aspirine : C₇H₆O₃ + C₄H₆O₃ → C₉H₈O₄ + C₂H₄O₂, avec 3,3 g d’acide salicylique et 7,0 mL d’anhydride acétique (masse volumique 1,08 g/mL ; Correction : le manuel écrit 1,08 g.L⁻¹).\n1) Quantités initiales. 2) Bilan de matière. 3) Masses à l’état final. 4) Masse d’acide salicylique pour un mélange stœchiométrique.",
  "a": "1) M(C₇H₆O₃) = 138 g/mol ⇒ 2,39 × 10⁻² mol. m(anhydride) = 7,56 g ; M = 102 g/mol ⇒ 7,41 × 10⁻² mol.\n2) L’acide salicylique est limitant : xmax = 2,39 × 10⁻² mol.\n3) Aspirine : 2,39 × 10⁻² × 180 ≈ 4,30 g ; acide acétique ≈ 1,43 g ; anhydride restant 5,02 × 10⁻² mol ≈ 5,12 g.\n4) 7,41 × 10⁻² × 138 ≈ 10,2 g."},
 {"k": "int", "src": "", "q": "Un camping-gaz contient 190 g de butane C₄H₁₀. Lors de la combustion complète, il se forme CO₂ et H₂O. (Vm = 24 L/mol ; l’air contient 1/5 de dioxygène en volume)\n1) Écrire l’équation de combustion.\n2) Quel volume de dioxygène faut-il pour brûler tout le butane ? Quel volume d’air ?\n3) Quelle masse de CO₂ rejette-t-on ? Pourquoi faut-il aérer la tente ?",
  "a": "1) 2C₄H₁₀ + 13O₂ → 8CO₂ + 10H₂O.\n2) n = 190/58 ≈ 3,28 mol ; n(O₂) = 6,5 × 3,28 ≈ 21,3 mol ⇒ V(O₂) ≈ 511 L ; V(air) ≈ 2,56 m³.\n3) n(CO₂) = 4 × 3,28 ≈ 13,1 mol ⇒ 577 g. La combustion consomme le dioxygène et, si l’air manque, elle devient incomplète et produit du monoxyde de carbone, très toxique."},
]

SERIES["Chimie – Chapitre II : La classification périodique des éléments"] = [
 {"k": "book", "src": "p. 43, ex. 4", "q": "L’atome d’aluminium possède 13 électrons et 27 nucléons (e = 1,6 × 10⁻¹⁹ C).\na) Charge totale des électrons. b) Charge du noyau et nombre de protons. c) Nombre de charge. d) Représentation symbolique.",
  "a": "a) q = −13 × 1,6 × 10⁻¹⁹ = −2,08 × 10⁻¹⁸ C.\nb) L’atome est neutre : le noyau porte +2,08 × 10⁻¹⁸ C, soit 13 protons.\nc) Z = 13.\nd) ²⁷₁₃Al (14 neutrons)."},
 {"k": "book", "src": "p. 43, ex. 5", "q": "La masse d’un atome X est 3,84 × 10⁻²⁶ kg et la charge de son noyau est 17,6 × 10⁻¹⁹ C (masse d’un nucléon : 1,67 × 10⁻²⁷ kg).\n1) Composition du noyau et nombre d’électrons. 2) Identifier l’élément. 3) Représentation symbolique.",
  "a": "1) Z = 17,6 × 10⁻¹⁹/1,6 × 10⁻¹⁹ = 11 protons ; A = 3,84 × 10⁻²⁶/1,67 × 10⁻²⁷ ≈ 23 nucléons, donc 12 neutrons ; 11 électrons.\n2) Z = 11 : le sodium.\n3) ²³₁₁Na."},
 {"k": "book", "src": "p. 43, ex. 6", "q": "Le chlore (Z = 17) a deux isotopes de 18 et 20 neutrons.\n1) Les représenter. 2) Masse molaire de chacun. 3) Structure électronique de l’ion Cl⁻. 4) Sachant que M(Cl) = 35,5 g/mol, calculer le pourcentage de chaque isotope.",
  "a": "1) ³⁵₁₇Cl et ³⁷₁₇Cl.\n2) Environ 35 g/mol et 37 g/mol.\n3) Cl⁻ : (K)²(L)⁸(M)⁸.\n4) 35x + 37(1 − x) = 35,5 ⇒ x = 0,75 : 75 % de chlore 35 et 25 % de chlore 37."},
 {"k": "book", "src": "p. 43, ex. 7", "q": "Le noyau de phosphore renferme 30 nucléons et porte q = 24 × 10⁻¹⁹ C.\n1) Nombre de protons. 2) Symbole du noyau. 3) Structure électronique. 4) L’atome gagne trois électrons : symbole et structure de l’ion obtenu ; composition de son noyau.",
  "a": "1) Z = 24/1,6 = 15.\n2) ³⁰₁₅P.\n3) (K)²(L)⁸(M)⁵.\n4) P³⁻ : (K)²(L)⁸(M)⁸ ; le noyau ne change pas : 15 protons et 15 neutrons."},
 {"k": "book", "src": "p. 44, ex. 8", "q": "L’aluminium a pour formule électronique (K)²(L)⁸(M)³.\n1) Nombre de charge. 2) Symbole du noyau (14 neutrons). 3) Masse molaire approchée. 4) Structure électronique de Al³⁺. 5) Position dans le tableau périodique.",
  "a": "1) Z = 13. 2) ²⁷₁₃Al. 3) M ≈ 27 g/mol. 4) Al³⁺ : (K)²(L)⁸. 5) 3e période (couche M externe), 13e colonne (3e groupe des éléments principaux), car 3 électrons périphériques."},
 {"k": "book", "src": "p. 44, ex. 10", "q": "Un jeune sportif doit consommer 1 g de calcium par jour ; 100 g de lait contiennent 133 mg de calcium ; masse volumique du lait 1,031 g/cm³.\n1) Volume de lait nécessaire. 2) Nombre de verres de 200 cm³.",
  "a": "1) m(lait) = 1000/1,33 ≈ 752 g ; V = 752/1,031 ≈ 729 cm³ (environ 0,73 L).\n2) 729/200 ≈ 3,6 : il faut un peu moins de 4 verres."},
 {"k": "extra", "src": "", "q": "Le soufre est situé dans la 3e période et la 16e colonne (6 électrons périphériques).\n1) Structure électronique et numéro atomique. 2) Quel ion simple donne-t-il ? 3) Citer un élément de la même famille.",
  "a": "1) (K)²(L)⁸(M)⁶ : Z = 16.\n2) Il gagne 2 électrons pour avoir l’octet : S²⁻.\n3) L’oxygène (Z = 8), juste au-dessus."},
 {"k": "int", "src": "", "q": "Une étiquette d’eau minérale indique : calcium 80 mg/L, magnésium 24 mg/L, sodium 9,2 mg/L.\n1) Donner la structure électronique de Ca (Z = 20), Mg (Z = 12) et Na (Z = 11) et les ions qu’ils forment.\n2) Calculer la concentration molaire de chaque ion (M : Ca 40 ; Mg 24 ; Na 23 g/mol).\n3) Pourquoi Ca et Mg ont-ils des propriétés voisines ?",
  "a": "1) Ca : (K)²(L)⁸(M)⁸(N)² → Ca²⁺ ; Mg : (K)²(L)⁸(M)² → Mg²⁺ ; Na : (K)²(L)⁸(M)¹ → Na⁺.\n2) [Ca²⁺] = 0,080/40 = 2,0 × 10⁻³ mol/L ; [Mg²⁺] = 1,0 × 10⁻³ mol/L ; [Na⁺] = 4,0 × 10⁻⁴ mol/L.\n3) Ils ont tous deux 2 électrons périphériques : ils sont dans la même colonne (alcalino-terreux)."},
]

SERIES["Chimie – Chapitre III : Molécules et ions"] = [
 {"k": "book", "src": "p. 59, ex. 1", "q": "1) Structure électronique et représentation de Lewis des atomes de carbone (Z = 6) et d’hydrogène (Z = 1). 2) Nombre de liaisons covalentes de chacun. 3) Formules développées du méthane CH₄ et de l’acétylène C₂H₂.",
  "a": "1) C : (K)²(L)⁴, 4 électrons de valence (4 électrons célibataires dans le schéma de Lewis) ; H : (K)¹.\n2) Le carbone forme 4 liaisons (tétravalent), l’hydrogène 1 (monovalent).\n3) CH₄ : un C relié à quatre H par des liaisons simples. C₂H₂ : H–C≡C–H (liaison triple entre les deux C)."},
 {"k": "book", "src": "p. 59, ex. 3", "q": "1) Définir les liaisons covalentes simple, double et triple. 2) Schémas de Lewis de O₂, N₂ et CO₂ et types de liaisons.",
  "a": "1) Mise en commun d’un, deux ou trois doublets d’électrons entre deux atomes.\n2) O₂ : O=O (double liaison, deux doublets non liants sur chaque O). N₂ : N≡N (triple liaison, un doublet non liant sur chaque N). CO₂ : O=C=O (deux doubles liaisons)."},
 {"k": "book", "src": "p. 59, ex. 4", "q": "1) Quels ions obtient-on à partir des atomes de sodium (Z = 11) et d’oxygène (Z = 8) ? 2) Équations de passage de l’atome à l’ion. 3) Dans l’oxyde de sodium, dans quel rapport sont ces ions ?",
  "a": "1) Na⁺ et O²⁻.\n2) Na → Na⁺ + e⁻ ; O + 2e⁻ → O²⁻.\n3) Le solide est neutre : deux Na⁺ pour un O²⁻ ; formule Na₂O."},
 {"k": "book", "src": "p. 60, ex. 6", "q": "C (Z = 6), F (9), Na (11), Mg (12), Cl (17).\n1) Structures électroniques ; éléments ayant le même nombre d’électrons de valence. 2) Formule brute et schéma de Lewis du tétrafluorométhane. 3) Ions simples de Mg, Cl, Na, F ; formule du chlorure de magnésium.",
  "a": "1) C : K²L⁴ ; F : K²L⁷ ; Na : K²L⁸M¹ ; Mg : K²L⁸M² ; Cl : K²L⁸M⁷. F et Cl ont 7 électrons de valence.\n2) CF₄ : C central lié à quatre F par des liaisons simples, chaque F portant 3 doublets non liants ; liaisons covalentes polarisées (F plus électronégatif).\n3) Mg²⁺, Cl⁻, Na⁺, F⁻ ; chlorure de magnésium : MgCl₂."},
 {"k": "book", "src": "p. 61, ex. 7", "q": "P (Z = 15) et Cl (Z = 17). 1) Positions dans le tableau ; lequel est le plus électronégatif ? 2) Nature de la liaison P–Cl, nombre de liaisons du phosphore, formule et schéma de Lewis de la molécule.",
  "a": "1) P : 3e période, 15e colonne (5 électrons de valence) ; Cl : 3e période, 17e colonne. Cl est plus électronégatif (plus à droite dans la même période).\n2) Liaison covalente polarisée (δ+ sur P, δ− sur Cl). P forme 3 liaisons : PCl₃ (P central avec un doublet non liant, chaque Cl avec 3 doublets non liants)."},
 {"k": "book", "src": "p. 61, ex. 9", "q": "1) Schémas de Lewis de H₂O, H₂O₂ et NH₃. 2) Expliquer la formation de NH₄⁺ et H₃O⁺. 3) L’ion bichromate contient 2 Cr et 7 O et porte deux charges négatives : formule ? Formule du bichromate de potassium ? 4) Formule du chlorure d’ammonium.",
  "a": "1) H–O–H (2 doublets non liants sur O) ; H–O–O–H ; NH₃ (N avec 3 liaisons et 1 doublet non liant).\n2) Le doublet non liant de N (ou de O) capte un ion H⁺ : NH₃ + H⁺ → NH₄⁺ ; H₂O + H⁺ → H₃O⁺.\n3) Cr₂O₇²⁻ ; K₂Cr₂O₇.\n4) NH₄Cl."},
 {"k": "extra", "src": "", "q": "Écrire la formule brute des composés ioniques formés par : a) Al³⁺ et O²⁻ ; b) Ca²⁺ et Cl⁻ ; c) Fe³⁺ et SO₄²⁻.",
  "a": "La somme des charges doit être nulle : a) Al₂O₃ ; b) CaCl₂ ; c) Fe₂(SO₄)₃."},
 {"k": "int", "src": "", "q": "Le sel de table est le chlorure de sodium NaCl ; le gaz qui sert à désinfecter l’eau est le dichlore Cl₂.\n1) Expliquer pourquoi NaCl est un composé ionique alors que Cl₂ est une molécule.\n2) Écrire le schéma de Lewis de Cl₂.\n3) Dans l’eau de Javel on trouve l’ion hypochlorite ClO⁻. Proposer un schéma de Lewis.",
  "a": "1) Na cède facilement son électron périphérique et Cl en capte un : il se forme des ions Na⁺ et Cl⁻ qui s’attirent. Deux atomes de chlore identiques mettent en commun un doublet : liaison covalente.\n2) Cl–Cl, chaque Cl portant 3 doublets non liants.\n3) [Cl–O]⁻ : liaison simple, 3 doublets non liants sur Cl et 3 sur O (O porte la charge négative)."},
]

SERIES["Chimie – Chapitre IV : Les ions en solution"] = [
 {"k": "book", "src": "p. 76, ex. 4", "q": "On dissout m₁ = 1,42 g de sulfate de sodium Na₂SO₄ (électrolyte fort) pour obtenir V₁ = 100 mL de solution S₁.\n1) Équation de dissociation. 2) Concentration C₁. 3) Concentrations des ions. 4) On ajoute 400 mL d’eau : nom de l’opération et nouvelle concentration.\n(O = 16 ; Na = 23 ; S = 32 g/mol)",
  "a": "1) Na₂SO₄ → 2Na⁺ + SO₄²⁻.\n2) M = 142 g/mol ; n = 0,010 mol ; C₁ = 0,10 mol/L.\n3) [Na⁺] = 0,20 mol/L ; [SO₄²⁻] = 0,10 mol/L.\n4) Une dilution ; C₂ = 0,010/0,500 = 0,020 mol/L."},
 {"k": "book", "src": "p. 76, ex. 5", "q": "À partir d’une solution S₁ de KNO₃ à C₁ = 10⁻¹ mol/L, préparer V₂ = 100 mL de solution S₂ à C₂ = 10⁻² mol/L.\n1) Mode opératoire et matériel. 2) Équation d’ionisation. 3) Molarité des ions dans S₂.",
  "a": "1) V₁ = C₂V₂/C₁ = 10 mL : on prélève 10 mL de S₁ avec la pipette jaugée de 10 mL, on les verse dans la fiole jaugée de 100 mL, on complète avec de l’eau distillée jusqu’au trait de jauge et on agite.\n2) KNO₃ → K⁺ + NO₃⁻.\n3) [K⁺] = [NO₃⁻] = 10⁻² mol/L."},
 {"k": "book", "src": "p. 76, ex. 6", "q": "Solution S de sulfate de fer III Fe₂(SO₄)₃, C = 0,02 mol/L, V = 200 mL.\n1) Équation de dissociation. 2) Molarités des ions. 3) Masse dissoute. 4) On ajoute de la soude à C′ = 0,1 mol/L : a) nom et couleur du précipité ; b) équation ; c) volume V′ pour précipiter tous les ions Fe³⁺ ; d) masse du précipité.\n(O = 16 ; H = 1 ; Fe = 56 ; S = 32 g/mol)",
  "a": "1) Fe₂(SO₄)₃ → 2Fe³⁺ + 3SO₄²⁻.\n2) [Fe³⁺] = 0,04 mol/L ; [SO₄²⁻] = 0,06 mol/L.\n3) M = 400 g/mol ; n = 4,0 × 10⁻³ mol ; m = 1,6 g.\n4) a) Hydroxyde de fer III, couleur rouille. b) Fe³⁺ + 3HO⁻ → Fe(OH)₃. c) n(Fe³⁺) = 8,0 × 10⁻³ mol ⇒ n(HO⁻) = 2,4 × 10⁻² mol ⇒ V′ = 240 mL. d) M(Fe(OH)₃) = 107 g/mol ; m ≈ 0,856 g."},
 {"k": "book", "src": "p. 77, ex. 7", "q": "La solubilité de PbCl₂ est s = 1,6 × 10⁻² mol/L. On introduit m = 2 g de PbCl₂ dans V = 225 mL d’eau.\n1) Équation de dissociation. 2) Masse m′ non dissoute. 3) Volume minimal V′ d’eau à ajouter pour tout dissoudre.\n(Cl = 35,5 ; Pb = 207 g/mol)",
  "a": "1) PbCl₂ → Pb²⁺ + 2Cl⁻.\n2) M = 278 g/mol. On peut dissoudre 1,6 × 10⁻² × 0,225 = 3,6 × 10⁻³ mol, soit 1,0 g : m′ ≈ 1,0 g.\n3) n totale = 2/278 ≈ 7,19 × 10⁻³ mol ⇒ volume nécessaire 7,19 × 10⁻³/1,6 × 10⁻² ≈ 0,450 L ⇒ V′ ≈ 225 mL."},
 {"k": "book", "src": "p. 77, ex. 8", "q": "On dissout m = 3,25 g de FeCl₃ ; dans la solution [Cl⁻] = 0,06 mol/L.\n1) Équation de dissociation. 2) Volume V. 3) Comment identifier les ions présents ?\n(Cl = 35,5 ; Fe = 56 g/mol)",
  "a": "1) FeCl₃ → Fe³⁺ + 3Cl⁻.\n2) M = 162,5 g/mol ; n = 0,020 mol ; C = [Cl⁻]/3 = 0,02 mol/L ⇒ V = 1,0 L.\n3) Fe³⁺ : avec la soude, précipité rouille Fe(OH)₃ (Fe³⁺ + 3HO⁻ → Fe(OH)₃). Cl⁻ : avec le nitrate d’argent, précipité blanc AgCl qui noircit à la lumière (Ag⁺ + Cl⁻ → AgCl)."},
 {"k": "book", "src": "p. 77, ex. 9", "q": "On dissout m₁ = 4 g de sulfate de fer II FeSO₄ dans V₁ = 100 mL. On fait réagir 10 mL de cette solution avec 30 mL de potasse KOH à 0,2 mol/L.\n1) Concentration C₁. 2) Équation de précipitation, nom et couleur du précipité ; quel réactif est en excès ? 3) Masse du solide et concentrations des ions dans le filtrat.",
  "a": "1) M = 152 g/mol ; n = 2,63 × 10⁻² mol ; C₁ ≈ 0,263 mol/L.\n2) Fe²⁺ + 2HO⁻ → Fe(OH)₂, précipité vert d’hydroxyde de fer II. n(Fe²⁺) = 2,63 × 10⁻³ mol ; n(HO⁻) = 6,0 × 10⁻³ mol > 2 × 2,63 × 10⁻³ : HO⁻ est en excès.\n3) m = 2,63 × 10⁻³ × 90 ≈ 0,237 g. Dans 40 mL : [K⁺] = 0,15 mol/L ; [SO₄²⁻] ≈ 0,066 mol/L ; HO⁻ restant 7,4 × 10⁻⁴ mol ⇒ [HO⁻] ≈ 0,018 mol/L."},
 {"k": "extra", "src": "", "q": "Écrire les équations de précipitation avec les ions hydroxyde de : Cu²⁺, Fe²⁺, Fe³⁺, Al³⁺, Zn²⁺, et donner la couleur des précipités.",
  "a": "Cu²⁺ + 2HO⁻ → Cu(OH)₂ (bleu) ; Fe²⁺ + 2HO⁻ → Fe(OH)₂ (vert) ; Fe³⁺ + 3HO⁻ → Fe(OH)₃ (rouille) ; Al³⁺ + 3HO⁻ → Al(OH)₃ (blanc) ; Zn²⁺ + 2HO⁻ → Zn(OH)₂ (blanc)."},
 {"k": "int", "src": "", "q": "Un technicien doit identifier le contenu de trois flacons sans étiquette : sulfate de cuivre, chlorure de fer III et chlorure de sodium. Il dispose de soude et de nitrate d’argent.\n1) Proposer une démarche.\n2) Écrire les équations des réactions observées.",
  "a": "1) On verse quelques gouttes de soude dans un échantillon de chaque flacon : précipité bleu ⇒ sulfate de cuivre ; précipité rouille ⇒ chlorure de fer III ; rien ⇒ chlorure de sodium. On confirme avec le nitrate d’argent : précipité blanc (ions chlorure) pour le chlorure de fer III et le chlorure de sodium.\n2) Cu²⁺ + 2HO⁻ → Cu(OH)₂ ; Fe³⁺ + 3HO⁻ → Fe(OH)₃ ; Ag⁺ + Cl⁻ → AgCl."},
]

SERIES["Chimie – Chapitre V : Solutions basiques, indicateurs et neutralisation"] = [
 {"k": "book", "src": "p. 91, exercice résolu (9)", "q": "Quel volume VA d’acide chlorhydrique à CA = 0,04 mol/L faut-il pour neutraliser VB = 80 mL de soude à CB = 0,05 mol/L ? Quel indicateur utiliser ? (Correction : le corrigé du manuel calcule avec 40 mL au lieu de 80 mL et trouve 50 mL.)",
  "a": "À l’équivalence CA × VA = CB × VB ⇒ VA = 0,05 × 80/0,04 = 100 mL. Le BBT convient (zone de virage autour de pH 7)."},
 {"k": "book", "src": "p. 93, ex. 4", "q": "Le pH de l’eau pure est 7,5 à 0 °C et 6,6 à 50 °C. Calculer [H₃O⁺] et [OH⁻] à ces deux températures.",
  "a": "Dans l’eau pure [H₃O⁺] = [OH⁻] = 10^(−pH). À 0 °C : ≈ 3,2 × 10⁻⁸ mol/L ; à 50 °C : ≈ 2,5 × 10⁻⁷ mol/L. (L’eau reste neutre même si son pH n’est pas 7.)"},
 {"k": "book", "src": "p. 93, ex. 6 et 7", "q": "1) Concentrations des ions dans des solutions d’acide chlorhydrique de pH 2 ; 3,5 ; 4,2, puis leurs concentrations massiques.\n2) pH des solutions : CA = 10⁻² mol/L ; CB = 3 × 10⁻⁴ mol/L ; CC = 0,5 g/L ; CD = 0,365 g/L. (M(HCl) = 36,5 g/mol)",
  "a": "1) [H₃O⁺] = [Cl⁻] = 1,0 × 10⁻² ; 3,2 × 10⁻⁴ ; 6,3 × 10⁻⁵ mol/L ; concentrations massiques 0,365 g/L ; 1,15 × 10⁻² g/L ; 2,3 × 10⁻³ g/L.\n2) pH(A) = 2 ; pH(B) ≈ 3,5 ; CC = 0,5/36,5 ≈ 1,37 × 10⁻² mol/L ⇒ pH ≈ 1,9 ; CD = 0,01 mol/L ⇒ pH = 2."},
 {"k": "book", "src": "p. 94, ex. 9", "q": "À partir d’une solution S₁ d’acide chlorhydrique à 0,8 mol/L, préparer 4 L de solution S₂ à 0,01 mol/L. Procédure, pH obtenu, masse de HCl dissous.",
  "a": "V₁ = 0,01 × 4/0,8 = 0,050 L : on prélève 50 mL de S₁ et on complète à 4 L avec de l’eau distillée. pH = 2. n = 0,04 mol ⇒ m = 1,46 g."},
 {"k": "book", "src": "p. 94, ex. 10", "q": "On mélange 50 cm³ d’acide chlorhydrique de pH 2 et 100 cm³ de pH 3. Concentration de la solution obtenue et pH.",
  "a": "n = 0,050 × 10⁻² + 0,100 × 10⁻³ = 6,0 × 10⁻⁴ mol dans 0,150 L : C = [Cl⁻] = [H₃O⁺] = 4,0 × 10⁻³ mol/L ; pH ≈ 2,4."},
 {"k": "book", "src": "p. 94, ex. 12 et 13", "q": "1) Une solution de soude contient 20 g/L de NaOH : concentration et pH. 2) Masse de NaOH pour 1 L de solution à 0,4 mol/L et pH de cette solution. (M(NaOH) = 40 g/mol ; à 25 °C [H₃O⁺][OH⁻] = 10⁻¹⁴)",
  "a": "1) C = 0,5 mol/L ; [H₃O⁺] = 10⁻¹⁴/0,5 = 2 × 10⁻¹⁴ ⇒ pH ≈ 13,7.\n2) m = 16 g ; pH = 14 + log 0,4 ≈ 13,6."},
 {"k": "extra", "src": "", "q": "On dose 20 mL d’une solution de soude par de l’acide chlorhydrique à 0,10 mol/L en présence de BBT ; le virage se produit pour 12,5 mL d’acide. Concentration de la soude ? Couleur du BBT avant et après l’équivalence ?",
  "a": "CB = 0,10 × 12,5/20 = 0,0625 mol/L. Le BBT est bleu en milieu basique (avant l’équivalence), vert à l’équivalence et jaune après (acide en excès)."},
 {"k": "int", "src": "", "q": "Un détartrant contient de l’acide chlorhydrique. On dilue 10 fois le produit puis on dose 10 mL de la solution diluée par de la soude à 0,50 mol/L : l’équivalence est obtenue pour 16 mL.\n1) Concentration de la solution diluée, puis du produit commercial.\n2) Pourquoi porter des gants et des lunettes ?",
  "a": "1) C × 10 = 0,50 × 16 ⇒ C = 0,80 mol/L ; produit commercial : 8,0 mol/L (environ 292 g/L de HCl).\n2) Solution très acide (pH proche de 0), corrosive pour la peau et les yeux."},
]
